// The iOS side of the pave app, over the UniFFI bindings (generated into
// iosApp/generated by build-rust.sh): the wallet's keystore in the Secure
// Enclave, App Attest at joining, and the wallet the shared screens call.
//
// Not built here: Xcode and the iOS SDK aren't available on the machine
// this was written on. The Rust side and its bindings are; the Python
// check in mobile/tests/uniffi exercises the same interface.
import DeviceCheck
import Foundation
import Security

/// The wallet's state sealed to Secure Enclave P-256 keys, a fresh key per
/// save, older ones deleted on commit. The enclave can't do AES itself, so
/// each seal is ECIES to the key's public half; only the enclave opens it.
/// iOS offers apps no rollback resistance: a same-device backup restores
/// the keys too (docs/phone-keys.md).
final class EnclaveVault: Keystore {
    let prefix: String
    private let alg: SecKeyAlgorithm = .eciesEncryptionStandardVariableIVX963SHA256AESGCM

    init(prefix: String) { self.prefix = prefix }

    private func tag(_ v: UInt32) -> Data { "\(prefix).v\(v)".data(using: .utf8)! }

    private func key(_ v: UInt32) -> SecKey? {
        let q: [String: Any] = [kSecClass as String: kSecClassKey, kSecAttrApplicationTag as String: tag(v), kSecReturnRef as String: true]
        var out: CFTypeRef?
        return SecItemCopyMatching(q as CFDictionary, &out) == errSecSuccess ? (out as! SecKey) : nil
    }

    private func versions() -> [UInt32] {
        let q: [String: Any] = [kSecClass as String: kSecClassKey, kSecMatchLimit as String: kSecMatchLimitAll, kSecReturnAttributes as String: true]
        var out: CFTypeRef?
        guard SecItemCopyMatching(q as CFDictionary, &out) == errSecSuccess, let items = out as? [[String: Any]] else { return [] }
        return items.compactMap { ($0[kSecAttrApplicationTag as String] as? Data).flatMap { String(data: $0, encoding: .utf8) } }
            .filter { $0.hasPrefix(prefix + ".v") }.compactMap { UInt32($0.dropFirst(prefix.count + 2)) }.sorted()
    }

    func seal(data: Data) throws -> Data {
        let v = (versions().last ?? 0) + 1
        let access = SecAccessControlCreateWithFlags(nil, kSecAttrAccessibleWhenUnlockedThisDeviceOnly, .privateKeyUsage, nil)!
        let attrs: [String: Any] = [
            kSecAttrKeyType as String: kSecAttrKeyTypeECSECPrimeRandom, kSecAttrKeySizeInBits as String: 256,
            kSecAttrTokenID as String: kSecAttrTokenIDSecureEnclave,
            kSecPrivateKeyAttrs as String: [kSecAttrIsPermanent as String: true, kSecAttrApplicationTag as String: tag(v), kSecAttrAccessControl as String: access],
        ]
        var err: Unmanaged<CFError>?
        guard let priv = SecKeyCreateRandomKey(attrs as CFDictionary, &err), let pub = SecKeyCopyPublicKey(priv),
              let ct = SecKeyCreateEncryptedData(pub, alg, data as CFData, &err) as Data? else {
            throw PaveError.Failed(message: err.map { "\($0.takeRetainedValue())" } ?? "sealing failed")
        }
        var be = v.bigEndian
        return Data(bytes: &be, count: 4) + ct
    }

    func open(sealed: Data) throws -> Data {
        let v = sealed.prefix(4).reduce(UInt32(0)) { $0 << 8 | UInt32($1) }
        guard let priv = key(v) else { throw PaveError.Failed(message: "sealed under a retired key: an old copy") }
        var err: Unmanaged<CFError>?
        guard let pt = SecKeyCreateDecryptedData(priv, alg, sealed.dropFirst(4) as CFData, &err) as Data? else {
            throw PaveError.Failed(message: err.map { "\($0.takeRetainedValue())" } ?? "opening failed")
        }
        return pt
    }

    func commit() throws {
        for v in versions().dropLast() {
            SecItemDelete([kSecClass as String: kSecClassKey, kSecAttrApplicationTag as String: tag(v)] as CFDictionary)
        }
    }

    func rollbackResistant() -> Bool { false }
}

private func hex(_ d: Data) -> String { d.map { String(format: "%02x", $0) }.joined() }

private func unhex(_ s: String) -> Data {
    var d = Data(); var i = s.startIndex
    while i < s.endIndex { let j = s.index(i, offsetBy: 2); d.append(UInt8(s[i..<j], radix: 16)!); i = j }
    return d
}

/// Joining a town from an iPhone: the request, App Attest's attestation of
/// a new key binding the join's challenge, and finishing with the town's reply.
final class IosJoin {
    private let join = Join()
    private let vault: EnclaveVault
    private(set) var request: (hex: String, challenge: String)

    init(vault: EnclaveVault) {
        self.vault = vault
        request = IosJoin.parse(join.request())
    }

    private static func parse(_ json: String) -> (String, String) {
        let o = (try? JSONSerialization.jsonObject(with: Data(json.utf8))) as? [String: Any] ?? [:]
        return (o["request"] as? String ?? "", o["challenge"] as? String ?? "")
    }

    func attest() async throws {
        let service = DCAppAttestService.shared
        guard service.isSupported else { throw PaveError.Failed(message: "App Attest isn't supported on this device") }
        let keyId = try await service.generateKey()
        let object = try await service.attestKey(keyId, clientDataHash: unhex(request.challenge))
        let body: [String: Any] = ["apple": ["object": hex(object), "key_id": hex(Data(base64Encoded: keyId)!)]]
        let json = String(data: try JSONSerialization.data(withJSONObject: body), encoding: .utf8)!
        request = IosJoin.parse(try join.attest(attestationJson: json))
    }

    func finish(reply: String, name: String, path: String) throws -> Wallet {
        try join.finish(replyHex: reply, name: name, path: path, keystore: vault)
    }
}
